// NFL final-score stats for the stat videos: the same numbers as the website's
// data page (/best-football-squares-numbers), generated by scripts/seo/stats.ts
// from nflverse games.csv into scripts/seo/data/nflFinals.ts.

import { TOP_FINALS as ALL_FINALS, DIGIT_SHARE, GAMES, HITS, SEASONS } from "../../../scripts/seo/data/nflFinals.ts";

export { DIGIT_SHARE, GAMES, HITS, SEASONS };

/** The five most common final scores, as [winner, loser, games]. */
export const TOP_FINALS = ALL_FINALS.slice(0, 5);

/** Chance (%) that a square hits on the final score. */
export const pct = (x: number, y: number): number => (100 * HITS[x][y]) / GAMES;
